+//! Detect active AI coding agents from environment variables.
+//!
+//! This crate is intentionally small and conservative. It detects agent-driven
+//! command execution, not merely an interactive terminal inside an editor that
+//! happens to offer AI features.
+
+#![forbid(unsafe_code)]
+
+use std::env;
+use std::ffi::{OsStr, OsString};
+use std::fmt;
+
+/// An AI coding agent known to the detector.
+#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
+#[non_exhaustive]
+pub enum Agent {
+    Amp,
+    AmazonQ,
+    Antigravity,
+    Augment,
+    ClaudeCode,
+    ClaudeCowork,
+    Cline,
+    CodeBuddy,
+    Codex,
+    Crush,
+    Cursor,
+    Firebender,
+    GeminiCli,
+    GitHubCopilot,
+    Goose,
+    Grok,
+    IflowCli,
+    Kiro,
+    OpenCode,
+    OpenHands,
+    Pi,
+    QwenCode,
+    Replit,
+    RooCode,
+    Trae,
+    VeCli,
+    Warp,
+    /// An agent identified only through the vendor-neutral `AI_AGENT` or
+    /// `AGENT` variable.
+    Other,
+}
+
